#!/usr/bin/env python3
"""Create one self-contained local HTML file from the intentionally synthetic design fixture."""
from pathlib import Path
ROOT=Path(__file__).resolve().parent
html=ROOT/'mock.html'
css=(ROOT/'styles.css').read_text()
data=(ROOT/'data-demo.js').read_text()
js=(ROOT/'app.js').read_text()
html.write_text('''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>app-insight · Applications — application-first mock</title><style>''' + css + '''</style></head><body><div class="sidebar-overlay" id="sideOverlay" onclick="state.mobileNav=false;header()"></div><div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-icon"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m12 2 9 5-9 5-9-5zM3 12l9 5 9-5M3 17l9 5 9-5"/></svg></span><div>app-insight<div class="brand-sub">Application intelligence</div></div></div><div class="side-title">Workspace</div><button class="side-link active" onclick="showInventory()"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg> Applications</button><div class="side-meta"><strong>Explore an application</strong><p>AS-IS, architecture, engineering controls, findings and evidence — all in one place.</p><span>● LOCAL · SYNTHETIC PREVIEW</span></div></aside><div class="workspace"><header class="topbar"><div class="flex"><button class="menu-btn" aria-label="Open navigation" onclick="state.mobileNav=!state.mobileNav;header()">☰</button><div class="crumb" id="crumb">Applications</div></div><div class="top-actions"><div class="local"><span class="dot"></span> Offline prototype</div><span class="top-id">Read-only · Example data</span></div></header><main class="main" id="main"></main></div></div><div id="drawerRoot"></div><script>''' + data + '\n' + js + '''</script></body></html>''')
print('Wrote',html,html.stat().st_size,'bytes')
